// IdentityServiceServer is the server API for IdentityService service.
// All implementations must embed UnimplementedIdentityServiceServer
// for forward compatibility.
//
// IdentityService is the people side of the platform (phase 38): users who sign up, own an account and manage its apps and keys.
// Only the gateway calls it. Everything after sign-in takes the user id the gateway resolved from the session token and checks the
// membership itself, in SQL, so a request for another account's app finds nothing even if the gateway had a bug.
type IdentityServiceServer interface {
	// SignUp creates the user, an account and the owner membership in one transaction and mails a verification link. It opens no session, and it answers the
	// same whether the address was free or taken (in that case the existing owner is mailed instead), so it does not tell who has an account.
	SignUp(context.Context, *SignUpRequest) (*SignUpResponse, error)
	// SignIn checks the password and opens a session. Every failure (unknown e-mail, wrong password, locked) is the same error.
	SignIn(context.Context, *SignInRequest) (*SignInResponse, error)
	// SignOut revokes the session of the token. An unknown or already revoked token is not an error.
	SignOut(context.Context, *SignOutRequest) (*SignOutResponse, error)
	// GetSession resolves a session token to its user and memberships, and slides the expiry.
	GetSession(context.Context, *GetSessionRequest) (*GetSessionResponse, error)
	// VerifyEmail consumes a verification token and marks the address as proven. The token is single use and expires after 24 hours.
	VerifyEmail(context.Context, *VerifyEmailRequest) (*VerifyEmailResponse, error)
	// ResendVerification mails a new verification link to the signed-in user (at most one a minute); older links stop working.
	ResendVerification(context.Context, *ResendVerificationRequest) (*ResendVerificationResponse, error)
	// RequestPasswordReset mails a reset link when the address has an account. It always succeeds and never says whether the address is known.
	RequestPasswordReset(context.Context, *RequestPasswordResetRequest) (*RequestPasswordResetResponse, error)
	// ResetPassword consumes a reset token (single use, one hour), sets the new password, proves the address and revokes every session of the user.
	ResetPassword(context.Context, *ResetPasswordRequest) (*ResetPasswordResponse, error)
	// RequestLoginCode mails a six-digit one-time code to an address (phase 42). It always succeeds for a well-formed address and never says whether the address
	// has an account; at most one code a minute and five an hour per address are sent.
	RequestLoginCode(context.Context, *RequestLoginCodeRequest) (*RequestLoginCodeResponse, error)
	// VerifyLoginCode checks a code and opens a session. The code is single use, lives ten minutes and is burned after five wrong tries. An address without an
	// account gets one (a user and an organisation): the code proved the mailbox. Every failure is the same error.
	VerifyLoginCode(context.Context, *VerifyLoginCodeRequest) (*VerifyLoginCodeResponse, error)
	// SignInWithIdentity opens a session for a person an identity provider has authenticated (the gateway verified the provider's ID token; this service only
	// trusts the gateway). It finds the user by (provider, subject), else links to the user with the same verified address, else creates user and account.
	SignInWithIdentity(context.Context, *SignInWithIdentityRequest) (*SignInWithIdentityResponse, error)
	GetMyAccount(context.Context, *GetMyAccountRequest) (*GetMyAccountResponse, error)
	// RenameMyAccount renames an account; only an owner may.
	RenameMyAccount(context.Context, *RenameMyAccountRequest) (*RenameMyAccountResponse, error)
	// InviteMember mails an invitation to an address. An owner or administrator may invite, an owner may invite owners, and the inviter's own address must be
	// verified. A second invitation to the same address refreshes the first.
	InviteMember(context.Context, *InviteMemberRequest) (*InviteMemberResponse, error)
	// ListInvitations lists the open invitations of an account (owner or administrator).
	ListInvitations(context.Context, *ListInvitationsRequest) (*ListInvitationsResponse, error)
	// RevokeInvitation cancels an open invitation.
	RevokeInvitation(context.Context, *RevokeInvitationRequest) (*RevokeInvitationResponse, error)
	// ResendInvitation mails a new link for an open invitation (at most one a minute); the old link stops working.
	ResendInvitation(context.Context, *ResendInvitationRequest) (*ResendInvitationResponse, error)
	// UpdateMemberRole changes a member's role. The last owner of an account cannot be demoted.
	UpdateMemberRole(context.Context, *UpdateMemberRoleRequest) (*UpdateMemberRoleResponse, error)
	// RemoveMember removes a member, or lets a member leave (their own id). The last owner cannot be removed.
	RemoveMember(context.Context, *RemoveMemberRequest) (*RemoveMemberResponse, error)
	// LookupInvitation says what a live invitation token is for, so the accept page can ask for the right thing. Public: the token is the credential.
	LookupInvitation(context.Context, *LookupInvitationRequest) (*LookupInvitationResponse, error)
	// AcceptInvitation turns an invitation into a new user (verified, because the token was mailed to the address) who is a member of the account, with a
	// session. For an address that has a user already it fails with identity.invite.sign_in_required: that person signs in and uses AcceptInvitationAsUser.
	AcceptInvitation(context.Context, *AcceptInvitationRequest) (*AcceptInvitationResponse, error)
	// AcceptInvitationAsUser adds the signed-in user to the account when the invitation was sent to the user's own address.
	AcceptInvitationAsUser(context.Context, *AcceptInvitationAsUserRequest) (*AcceptInvitationAsUserResponse, error)
	// CreateMyApp adds an app (a sandbox and a live tenant) to an account the user owns or administers. Free tier, no grace period.
	CreateMyApp(context.Context, *CreateMyAppRequest) (*CreateMyAppResponse, error)
	ListMyApps(context.Context, *ListMyAppsRequest) (*ListMyAppsResponse, error)
	GetMyApp(context.Context, *GetMyAppRequest) (*GetMyAppResponse, error)
	// ResolveMyTenant answers whether a tenant belongs to an app of an account the user is a member of. The gateway asks it before it lets a session act on a tenant.
	ResolveMyTenant(context.Context, *ResolveMyTenantRequest) (*ResolveMyTenantResponse, error)
	CreateMyApiKey(context.Context, *CreateMyApiKeyRequest) (*CreateMyApiKeyResponse, error)
	ListMyApiKeys(context.Context, *ListMyApiKeysRequest) (*ListMyApiKeysResponse, error)
	RevokeMyApiKey(context.Context, *RevokeMyApiKeyRequest) (*RevokeMyApiKeyResponse, error)
	// RotateMyApiKey issues a replacement with the same scope and lets the old key live for an overlap window, so a deployment can switch without a gap.
	RotateMyApiKey(context.Context, *RotateMyApiKeyRequest) (*RotateMyApiKeyResponse, error)
	// GetMyGoLive computes the go-live checklist of an app's live environment. provider_ready is what the gateway learned from payments-worker.
	GetMyGoLive(context.Context, *GetMyGoLiveRequest) (*GetMyGoLiveResponse, error)
	// ActivateMyApp activates the live environment when every item is done (the owner only).
	ActivateMyApp(context.Context, *ActivateMyAppRequest) (*ActivateMyAppResponse, error)
	// PromoteMyApp copies the configuration of an app's sandbox to its live environment (meters, plans and prices, taxes, coupons, webhook endpoints, mail
	// settings), never customers, usage, invoices or payments. With dry_run it only returns the diff. It only adds: what exists in live and differs is
	// reported as a conflict and left alone.
	PromoteMyApp(context.Context, *PromoteMyAppRequest) (*PromoteMyAppResponse, error)
	// ResetMySandbox starts the reset of an app's sandbox: an asynchronous job that deletes its customers, subscriptions, usage, invoices and payments and keeps its
	// configuration. Owners and admins; at most one running per sandbox and one every few minutes.
	ResetMySandbox(context.Context, *ResetMySandboxRequest) (*ResetMySandboxResponse, error)
	// GetMySandboxReset returns the latest reset of an app's sandbox, running or finished; unset when there has been none.
	GetMySandboxReset(context.Context, *GetMySandboxResetRequest) (*GetMySandboxResetResponse, error)
	mustEmbedUnimplementedIdentityServiceServer()
}

